import{_ as a,o,c as l,a4 as r}from"./chunks/framework.9tZL7ZIQ.js";const c=JSON.parse('{"title":"富国银行（Wells Fargo & Company）","description":"","frontmatter":{},"headers":[],"relativePath":"03_companies/富国银行.md","filePath":"03_companies/富国银行.md"}'),e={name:"03_companies/富国银行.md"};function i(n,t,d,h,s,u){return o(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="富国银行-wells-fargo-company" tabindex="-1">富国银行（Wells Fargo &amp; Company） <a class="header-anchor" href="#富国银行-wells-fargo-company" aria-label="Permalink to &quot;富国银行（Wells Fargo &amp; Company）&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>内容</th></tr></thead><tbody><tr><td>英文名</td><td>Wells Fargo &amp; Company</td></tr><tr><td>行业</td><td>银行 / 金融服务</td></tr><tr><td>成立年份</td><td>1852年</td></tr><tr><td>创始人</td><td>Henry Wells、William Fargo（与<a href="/03_companies/美国运通.html">美国运通</a>同创始人）</td></tr><tr><td>总部</td><td>加利福尼亚州旧金山</td></tr><tr><td>伯克希尔持股</td><td>最高约 <strong>10.0%</strong>（2016年底），逐步减持后于2020年清仓</td></tr><tr><td>首次买入</td><td>1989年（第一批），1990年完成建仓</td></tr><tr><td>持仓时间</td><td><strong>31年</strong>（1989年 - 2020年）</td></tr><tr><td>初始投资成本</td><td><strong>2.894亿美元</strong>（买入10%股权）</td></tr><tr><td>买入时估值</td><td>对应整个银行估值约<strong>29亿美元</strong></td></tr></tbody></table><h2 id="核心业务" tabindex="-1">核心业务 <a class="header-anchor" href="#核心业务" aria-label="Permalink to &quot;核心业务&quot;">​</a></h2><p>富国银行是美国历史最悠久、规模最大的银行之一，核心业务包括：</p><ul><li><strong>社区银行</strong>：个人及小企业存贷款业务，拥有全美最广泛的分支网络之一</li><li><strong>批发银行</strong>：企业贷款、贸易融资、资本市场服务</li><li><strong>财富管理</strong>：资产管理、私人银行、投资顾问</li><li><strong>保险</strong>：银行保险及独立保险经纪</li></ul><p>富国银行以**&quot;交叉销售&quot;（cross-selling）**商业模式著称，其战略目标是向每位客户销售多种金融产品，提高单客价值和客户粘性。</p><h2 id="与巴菲特的关系" tabindex="-1">与巴菲特的关系 <a class="header-anchor" href="#与巴菲特的关系" aria-label="Permalink to &quot;与巴菲特的关系&quot;">​</a></h2><h3 id="早期建仓-1989-1990年-恐慌中买入" tabindex="-1">早期建仓（1989-1990年）：恐慌中买入 <a class="header-anchor" href="#早期建仓-1989-1990年-恐慌中买入" aria-label="Permalink to &quot;早期建仓（1989-1990年）：恐慌中买入&quot;">​</a></h3><p>巴菲特在1989-1990年储蓄贷款协会危机（S&amp;L Crisis）期间分批建仓富国银行：</p><ul><li>六分之一仓位在<strong>1989年</strong>买入，剩余六分之五在<strong>1990年</strong>完成建仓</li><li>最终买入<strong>500万股</strong>，花费<strong>2.894亿美元</strong>，获得富国银行约<strong>10%股权</strong></li><li>买入成本相当于整个银行估值仅<strong>29亿美元</strong>，而巴菲特认为，如果直接收购整个银行，需要支付<strong>两倍价格</strong></li><li>此次投资占到当时伯克希尔股票投资组合的<strong>近10%</strong>，因美联储监管限制，这已经是最大允许持股比例</li></ul><p>巴菲特建仓的背景：</p><ul><li>当时整个银行业陷入恐慌，市场担忧加州房地产泡沫破裂和大地震风险</li><li>富国银行股价下跌了<strong>约50%</strong></li><li>巴菲特看重的不是银行本身，而是<strong>优秀的管理层</strong></li></ul><h3 id="深度持有期-1990年代-2016年-四大金刚之一" tabindex="-1">深度持有期（1990年代-2016年）：四大金刚之一 <a class="header-anchor" href="#深度持有期-1990年代-2016年-四大金刚之一" aria-label="Permalink to &quot;深度持有期（1990年代-2016年）：四大金刚之一&quot;">​</a></h3><p>富国银行与<a href="/03_companies/美国运通.html">美国运通</a>、<a href="/03_companies/可口可乐.html">可口可乐</a>、<a href="/03_companies/吉列.html">吉列</a>并称为巴菲特的**&quot;四大金刚&quot;**（Big Four）核心持仓，在长达26年时间里一直是伯克希尔最重要的银行投资：</p><table tabindex="0"><thead><tr><th>时期</th><th>持股变化</th><th>关键数据</th></tr></thead><tbody><tr><td>1990年底</td><td>500万股</td><td>成本2.894亿，市值2.894亿</td></tr><tr><td>1992年底</td><td>635.8万股</td><td>成本3.810亿，市值4.856亿</td></tr><tr><td>1994年底</td><td>679.1万股</td><td>成本4.237亿，市值9.847亿</td></tr><tr><td>1999年底</td><td>5,913.7万股 *</td><td>成本3.49亿，市值239.1亿</td></tr><tr><td>2003年底</td><td>5,644.8万股</td><td>&quot;去年我们买入了一些富国银行的股票&quot;</td></tr><tr><td>2005年底</td><td>9,509.2万股</td><td>&quot;我们大幅增持了富国银行&quot;</td></tr><tr><td>2006年底</td><td>21,816.9万股</td><td>成本36.97亿，市值77.58亿</td></tr><tr><td>2009年底</td><td>33,423.6万股</td><td>成本73.94亿，市值90.21亿</td></tr><tr><td>2011年底</td><td>40,001.6万股</td><td>&quot;我们对富国银行头寸增加10亿美元&quot;，成本90.86亿</td></tr><tr><td>2012年底</td><td>45,617.0万股</td><td>增持后持股8.7%，成本109.06亿</td></tr><tr><td>2013年底</td><td>48,347.1万股</td><td>增持后持股9.2%，成本118.71亿</td></tr><tr><td>2016年底</td><td>50,000.0万股</td><td><strong>持股达到最高10.0%</strong>，成本127.30亿</td></tr><tr><td>2017年底</td><td>48,254.4万股</td><td>开始小幅减持</td></tr><tr><td>2018年底</td><td>44,934.9万股</td><td>继续减持至9.8%</td></tr><tr><td>2019年底</td><td>34,568.9万股</td><td>大幅减持至8.4%</td></tr><tr><td>2020年底</td><td><strong>清仓</strong></td><td>从伯克希尔重仓股名单消失</td></tr></tbody></table><p><em>注：1999年股数大幅增加是因为拆股</em></p><h3 id="管理层信任-1990年代-2000年代" tabindex="-1">管理层信任（1990年代-2000年代） <a class="header-anchor" href="#管理层信任-1990年代-2000年代" aria-label="Permalink to &quot;管理层信任（1990年代-2000年代）&quot;">​</a></h3><p>巴菲特长期信任富国银行的历任管理层：</p><ul><li><strong>卡尔·赖卡特（Carl Reichardt）<strong>和</strong>保罗·黑曾（Paul Hazen）</strong>：巴菲特买入时的管理层，两人配合默契，都深知控制成本的重要性，&quot;盈利好的时候也不敢乱扩张，下跌的时候也敢理性面对&quot;</li><li>1994年卡尔·赖卡特退休时，巴菲特专门在股东信中称赞他&quot;近年来遇到了非常艰难的行业条件，但他作为经理人的技能使他经营的业务以创纪录的收益、增加的光彩和光明的前景从这些时期中走出&quot;</li><li><strong>迪克·科瓦切维奇（Dick Kovacevich）</strong>：2000年代CEO，巴菲特将其列入&quot;让我非常钦佩；有许多大公司的管理者让我非常钦佩；<a href="/03_companies/美国运通.html">美国运通</a>的肯·切诺尔特、通用电气的杰夫·伊梅尔特和富国银行的迪克·科瓦切维奇很快就浮现在脑海中&quot;</li><li><strong>约翰·斯顿夫（John Stumpf）</strong>：2007-2016年CEO，金融危机期间巴菲特仍信任其能力</li></ul><h3 id="金融危机期间-2008-2009" tabindex="-1">金融危机期间（2008-2009） <a class="header-anchor" href="#金融危机期间-2008-2009" aria-label="Permalink to &quot;金融危机期间（2008-2009）&quot;">​</a></h3><p>2008年金融危机期间，许多大型金融机构遭遇严重问题，富国银行CEO约翰·斯顿夫精辟总结：</p><blockquote><p>&quot;有意思的是，这个行业发明了新的赔钱方式，而旧方式明明效果很好。&quot;</p></blockquote><p>金融危机后：</p><ul><li>巴菲特继续增持，2009年底持股达到3.34亿股</li><li>2010年巴菲特指出，尽管美联储冻结了主要银行股息，但&quot;富国银行虽然在衰退最严重时期持续繁荣，目前享有巨大的财务实力和盈利能力，因此被迫维持人为的低派息&quot;，&quot;在某个时候，可能很快，美联储的限制将停止。富国银行随后可以恢复其所有者应得的理性股息政策。在那时，我们预计仅这一只证券的年度股息就将每年增加数亿美元&quot;</li></ul><h3 id="虚假账户丑闻-2016年-企业文化腐化" tabindex="-1">虚假账户丑闻（2016年）：企业文化腐化 <a class="header-anchor" href="#虚假账户丑闻-2016年-企业文化腐化" aria-label="Permalink to &quot;虚假账户丑闻（2016年）：企业文化腐化&quot;">​</a></h3><p>2016年，富国银行被曝光为达成交叉销售目标，管理层逼迫员工秘密开立了<strong>数百万个未经客户授权的虚假账户</strong>，以满足不切实际的销售指标。</p><p>丑闻发生后，巴菲特在后续年份逐步减持，但股东信中较少公开评论此事。</p><h3 id="最终清仓-2016-2020年-缓慢退出" tabindex="-1">最终清仓（2016-2020年）：缓慢退出 <a class="header-anchor" href="#最终清仓-2016-2020年-缓慢退出" aria-label="Permalink to &quot;最终清仓（2016-2020年）：缓慢退出&quot;">​</a></h3><ul><li>2016年丑闻后，伯克希尔开始缓慢减持</li><li>2017年减持至4.825亿股（9.9%）</li><li>2018年减持至4.493亿股（9.8%）</li><li>2019年大幅减持至3.457亿股（8.4%）</li><li><strong>2020年</strong>，伯克希尔完全清仓了剩余持仓，富国银行从年度重仓股名单中消失</li><li>结束了这一段长达<strong>31年</strong>的投资关系</li></ul><h2 id="核心竞争优势-巴菲特视角" tabindex="-1">核心竞争优势（巴菲特视角） <a class="header-anchor" href="#核心竞争优势-巴菲特视角" aria-label="Permalink to &quot;核心竞争优势（巴菲特视角）&quot;">​</a></h2><h3 id="_1-西海岸地缘优势" tabindex="-1">1. 西海岸地缘优势 <a class="header-anchor" href="#_1-西海岸地缘优势" aria-label="Permalink to &quot;1. 西海岸地缘优势&quot;">​</a></h3><ul><li>1852年创立于加州，起源早，历史悠久</li><li>在加州及西海岸各州分支网络极其密集</li><li>占据美国最富裕、经济最活跃的消费市场</li></ul><h3 id="_2-优秀的成本控制能力" tabindex="-1">2. 优秀的成本控制能力 <a class="header-anchor" href="#_2-优秀的成本控制能力" aria-label="Permalink to &quot;2. 优秀的成本控制能力&quot;">​</a></h3><ul><li>长期以来，运营效率在大型银行中表现最优</li><li>成本收入比长期保持行业低位</li><li>管理层在盈利好的时候也保持克制，不盲目扩张</li></ul><h3 id="_3-交叉销售模式" tabindex="-1">3. 交叉销售模式 <a class="header-anchor" href="#_3-交叉销售模式" aria-label="Permalink to &quot;3. 交叉销售模式&quot;">​</a></h3><ul><li>向单一客户销售多种金融产品（支票、储蓄、信用卡、贷款、保险等）</li><li>提高客户粘性，降低获客成本，提升单客利润率</li><li><strong>但</strong>：过度激进的销售指标最终导致了虚假账户丑闻，摧毁了企业文化</li></ul><h3 id="_4-保守的信贷文化" tabindex="-1">4. 保守的信贷文化 <a class="header-anchor" href="#_4-保守的信贷文化" aria-label="Permalink to &quot;4. 保守的信贷文化&quot;">​</a></h3><ul><li>早期管理层始终坚持保守的贷款政策</li><li>杠杆水平合理，避免过度承担风险</li><li>多次危机中表现优于同行</li></ul><h2 id="巴菲特评价摘录-原文摘自历年股东信" tabindex="-1">巴菲特评价摘录（原文摘自历年股东信） <a class="header-anchor" href="#巴菲特评价摘录-原文摘自历年股东信" aria-label="Permalink to &quot;巴菲特评价摘录（原文摘自历年股东信）&quot;">​</a></h2><blockquote><p>&quot;我们本来不喜欢银行业，银行业一般杠杆二十倍，一点点资产错误就能吃掉全部股权，过去很多大银行，经理都犯这个错，大家跟着领导走，大家都杠杆，都给垃圾贷款，结果就是大家一起完蛋，现在我们买富国银行，就是我们喜欢管理层，卡尔·赖卡特和保罗·黑曾，两个人，就像<a href="/search.html?q=首都城市ABC">首都城市ABC</a>汤姆·墨菲和丹·伯克，两个人加起来比单独一个强，都知道控制成本，盈利好的时候也不敢乱扩张，下跌的时候也敢理性面对，我们就是喜欢这样管理层，所以我们在市场恐慌的时候，富国银行跌了一半，我们买了，花了两亿九千万，买了10%，相当于我们买整个银行五十亿，我们要是直接买整个银行，就是两倍价格，而且你买整个银行，你也找不到这么好管理层，所以我们很开心能打折买好管理层好银行。&quot; —— <strong>1990年</strong></p></blockquote><blockquote><p>&quot;当然，加州银行真的遇到地震，大地震房贷出事，加州房地产过度建设，会不会出大事，我们觉得概率低，就算出事，我们买的价格也不贵，就算亏，我们也能接受，反正一年亏了，我们也开心，我们<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔哈撒韦</a>就喜欢这样，好企业股价跌了，我们反而开心买，我们就是永远买，股价跌了对我们好，涨了对我们不好，我们就是这样，下跌我们买，因为我们知道，我们一直要买，所以下跌让我们买更便宜，当然，悲观带来低价，好公司降价你才能买，这不代表逆向投资就是对，你还是要思考，不是说大家悲观你就买，你得思考，但是很多时候，悲观的时候才有好价格，乐观的时候价格高对你不好。&quot; —— <strong>1990年</strong></p></blockquote><blockquote><p>&quot;在<a href="/03_companies/富国银行.html">富国银行</a>——一家资产530亿美元的银行——我们13%的所有权转化为一家70亿美元的&quot;<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔哈撒韦</a>银行&quot;，该银行在1994年赚取了约1亿美元。拥有一大部分希望钻石远胜于拥有100%的莱茵石，刚才提到的公司完全有资格被称为稀世珍宝。&quot; —— <strong>1994年</strong></p></blockquote><blockquote><p>&quot;公平地说，我们也看到了很多成功案例，有些确实非常出色。有许多大公司的管理者让我非常钦佩；<a href="/03_companies/美国运通.html">美国运通</a>的肯·切诺尔特（Ken Chenault）、通用电气的杰夫·伊梅尔特（Jeff Immelt）和富国银行的迪克·科瓦切维奇（Dick Kovacevich）很快就浮现在脑海中。但我不认为我能胜任他们所做的管理工作。&quot; —— <strong>2006年</strong></p></blockquote><blockquote><p>&quot;然而，一些大型金融机构经历了惊人的问题，因为它们从事了我去年信中描述的&quot;宽松放贷行为&quot;。富国银行CEO约翰·斯顿夫精辟地总结了最近许多放贷者的行为：&quot;有意思的是，这个行业发明了新的赔钱方式，而旧方式明明效果很好。&quot;&quot; —— <strong>2007年</strong></p></blockquote><blockquote><p>&quot;有意思的是，<a href="/03_companies/美国运通.html">美国运通</a>和<a href="/03_companies/富国银行.html">富国银行</a>都是Henry Wells和William Fargo组织成立的，<a href="/03_companies/美国运通.html">美国运通</a>1850年，富国1852年。<a href="/03_companies/宝洁.html">宝洁</a>和<a href="/03_companies/可口可乐.html">可口可乐</a>分别1837年和1886年开始做生意。初创企业不是我们的游戏。&quot; —— <strong>2007年</strong></p></blockquote><blockquote><p>&quot;总体来说，我们对被投资企业经营表现感到高兴。2007年，我们四大持仓中的三个——<a href="/03_companies/美国运通.html">美国运通</a>、<a href="/03_companies/可口可乐.html">可口可乐</a>、<a href="/03_companies/宝洁.html">宝洁</a>——每股盈利增长12%、14%和14%。第四个，富国银行，因为房地产泡沫破裂，盈利小幅下降。然而，我相信即便如此，它内在价值还是小幅增长了。&quot; —— <strong>2007年</strong></p></blockquote><blockquote><p>&quot;我要强调，我们不会根据市场价格波动评估投资年度进步。我们评估进步的两个方法，应用到我们拥有的企业：第一个就是测试盈利增长，同时允许行业条件变化。第二个更主观，就是测试它的&quot;护城河&quot;——也就是竞争对手很难侵蚀它，这种让竞争者日子不好过的优势，过去一年有没有变宽。所有&quot;四大&quot;在这个测试上都得分正面。&quot; —— <strong>2007年</strong></p></blockquote><blockquote><p>&quot;银行业已经站稳脚跟，<a href="/03_companies/富国银行.html">富国银行</a>正在蓬勃发展。其收益强劲，资产稳健，资本处于创纪录水平。&quot; —— <strong>2011年</strong></p></blockquote><blockquote><p>&quot;梅·韦斯特说得对：&quot;好东西再多也不为过。&quot;&quot; —— <strong>2012年</strong>（谈及持续增持四大重仓）</p></blockquote><blockquote><p>&quot;这四家公司拥有卓越的业务，由既有才华又以股东利益为导向的管理层运营。在<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔哈撒韦</a>，我们更愿意持有一家优秀公司的可观但非控股股份，也不愿意100%持有一家平庸企业；拥有希望钻石的部分权益胜过拥有全部的人造钻石。&quot; —— <strong>2013年</strong></p></blockquote><h2 id="财务表现-伯克希尔视角" tabindex="-1">财务表现（伯克希尔视角） <a class="header-anchor" href="#财务表现-伯克希尔视角" aria-label="Permalink to &quot;财务表现（伯克希尔视角）&quot;">​</a></h2><h3 id="长期收益" tabindex="-1">长期收益 <a class="header-anchor" href="#长期收益" aria-label="Permalink to &quot;长期收益&quot;">​</a></h3><ul><li>1990年初始投资：2.894亿美元买入10%</li><li>2006年底：市值达到77.58亿美元，持仓成本36.97亿美元</li><li>2016年底：市值达到275.55亿美元，持仓成本127.30亿美元</li><li>30年间，通过公司留存收益再投资、股票回购，伯克希尔持股比例不断提升，收益持续增长</li></ul><h3 id="股息收入" tabindex="-1">股息收入 <a class="header-anchor" href="#股息收入" aria-label="Permalink to &quot;股息收入&quot;">​</a></h3><ul><li>2010年，巴菲特预计：&quot;在美联储限制取消后，我们仅从富国银行获得的年度股息就将每年增加数亿美元&quot;</li><li>随着公司持续盈利和股息增长，晚年每年为伯克希尔贡献数亿美元稳定股息</li></ul><h2 id="相关人物" tabindex="-1">相关人物 <a class="header-anchor" href="#相关人物" aria-label="Permalink to &quot;相关人物&quot;">​</a></h2><ul><li><strong>卡尔·赖卡特（Carl Reichardt）</strong> - 早期CEO，巴菲特极为赞赏的成本控制者</li><li><strong>保罗·黑曾（Paul Hazen）</strong> - 早期CEO，与赖卡特搭档</li><li><strong>迪克·科瓦切维奇（Dick Kovacevich）</strong> - 交叉销售模式的主要推动者</li><li><strong>约翰·斯顿夫（John Stumpf）</strong> - CEO任内爆发虚假账户丑闻</li><li><strong>Henry Wells</strong> - 联合创始人（同时也是<a href="/03_companies/美国运通.html">美国运通</a>创始人）</li><li><strong>William Fargo</strong> - 联合创始人（同时也是<a href="/03_companies/美国运通.html">美国运通</a>创始人）</li></ul><h2 id="投资教训" tabindex="-1">投资教训 <a class="header-anchor" href="#投资教训" aria-label="Permalink to &quot;投资教训&quot;">​</a></h2><h3 id="成功之处" tabindex="-1">成功之处 <a class="header-anchor" href="#成功之处" aria-label="Permalink to &quot;成功之处&quot;">​</a></h3><ul><li>在行业危机和市场恐慌中，敢于买入优质公司的低估股份</li><li>&quot;以50亿美元的价格买入价值100亿美元的好生意&quot;，安全边际足够</li><li>看重管理层品质，优秀管理层能够穿越周期</li><li>长期持有，享受企业复利增长和股票回购带来的持股比例提升</li></ul><h3 id="深刻教训" tabindex="-1">深刻教训 <a class="header-anchor" href="#深刻教训" aria-label="Permalink to &quot;深刻教训&quot;">​</a></h3><ul><li><strong>企业文化是动态的，可以腐化</strong>：即使拥有几十年优秀企业文化，错误的激励机制（不切实际的交叉销售指标）也能迅速摧毁信任和声誉</li><li>&quot;如果激励措施设计错了，好人也会做坏事&quot;</li><li><strong>即使是持有30年的好公司，也要持续监督</strong>：当企业文化和管理层行为发生根本性变化，需要有勇气认错退出</li><li><strong>交叉销售模式双刃剑</strong>：高效的客户开发模式一旦过度追求数字目标，就会变成损害客户利益和公司声誉的毒药</li></ul><h2 id="在股东信中的年份" tabindex="-1">在股东信中的年份 <a class="header-anchor" href="#在股东信中的年份" aria-label="Permalink to &quot;在股东信中的年份&quot;">​</a></h2><p>1990, 1991, 1992, 1993, 1994, 1995, 1996, 1997, 1998, 1999, 2000, 2001, 2002, 2003, 2004, 2005, 2006, 2007, 2008, 2009, 2010, 2011, 2012, 2013, 2014, 2015, 2016, 2017, 2018, 2019</p><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li><a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔哈撒韦</a> - 投资主体</li><li><a href="/03_companies/美国运通.html">美国运通</a> - 同期四大金刚持仓，创始人相同</li><li><a href="/03_companies/可口可乐.html">可口可乐</a> - 同期四大金刚持仓</li><li><a href="/03_companies/吉列.html">吉列</a> - 同期四大金刚持仓</li><li><a href="/03_companies/美国银行.html">美国银行</a> - 巴菲特后期增持的美国大型银行</li></ul><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该公司在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/03_companies/富国银行.html">1990年：完整翻译|/01_letters/1990年/翻译</a></li><li><a href="/03_companies/富国银行.html">2003年：完整翻译|/01_letters/2003年/翻译</a></li><li><a href="/03_companies/富国银行.html">2007年：完整翻译|/01_letters/2007年/翻译</a></li><li><a href="/03_companies/富国银行.html">2016年：完整翻译|/01_letters/2016年/翻译</a></li></ul><hr><p><em>最后更新：2026-04-16</em></p>',72)])])}const m=a(e,[["render",i]]);export{c as __pageData,m as default};
